/**
 * @file mujoco_sim.hpp
 * @brief ROS-free wrapper around one MuJoCo model: joint commands in, joint state and tool wrench out.
 * @details The ros2_control plugin (MujocoSystemInterface) is a thin shell over this class, so the
 *          physics side is testable without a controller manager. Built against MuJoCo 4.x.
 *
 *          Joint model: every commanded joint has one MuJoCo position actuator (generated by the
 *          MJCF generator). A command (position q*, velocity v*) is applied as
 *              ctrl = q* + (kv / kp) * v*
 *          which, for the actuator force kp (ctrl - q) - kv qdot, equals the PD law
 *          kp (q* - q) + kv (v* - qdot): velocity feed-forward without a second actuator.
 *
 *          Wrench: the model's force and torque sensors on the F/T site, in the site frame. MuJoCo
 *          reports the load carried through the site; the sign is flipped so that the result is the
 *          force and torque the environment applies to the tool (a wall pushing back on a tool
 *          that presses along +z_site reads a negative z force; see docs/sim_mujoco.md). The reading at
 *          activation can be removed (tare), which cancels the tool's own weight.
 */

#pragma once

#include <array>
#include <string>
#include <vector>

#include <mujoco/mujoco.h>

namespace sim_mujoco
{

using Wrench = std::array<double, 6>;  ///< fx fy fz tx ty tz

class MujocoSim
{
public:
  /// Loads the MJCF at `mjcf_path`. Throws std::runtime_error on any model or name error.
  MujocoSim(
    const std::string & mjcf_path, const std::vector<std::string> & joints,
    const std::string & ft_site = "ft_site");
  ~MujocoSim();
  MujocoSim(const MujocoSim &) = delete;
  MujocoSim & operator=(const MujocoSim &) = delete;

  size_t jointCount() const {return joint_.size();}
  double timestep() const {return model_->opt.timestep;}

  /// Set the commanded joints' positions (rad or m) and velocities zero, then re-satisfy the
  /// model's mimic (joint equality) constraints and run forward kinematics.
  void setJointPositions(const std::vector<double> & q);

  /// Position / velocity command of joint i (as ordered in the constructor). NaN means "none":
  /// a NaN position holds the last valid target, a NaN velocity counts as zero.
  void setCommand(size_t i, double position, double velocity);

  /// Advance the simulation by `dt` seconds (rounded down to whole MuJoCo steps; the remainder is
  /// carried to the next call). Returns the number of steps taken.
  int advance(double dt);

  double position(size_t i) const {return data_->qpos[joint_[i].qpos_adr];}
  double velocity(size_t i) const {return data_->qvel[joint_[i].dof_adr];}
  /// Applied actuator force (N or N m, after the force range clamp).
  double effort(size_t i) const {return data_->actuator_force[joint_[i].actuator];}
  double target(size_t i) const {return joint_[i].target;}

  /// Tool wrench (environment on tool, site frame), tare removed.
  Wrench wrench() const;
  /// Store the current raw reading as the zero point.
  void tareWrench();
  void clearTare() {tare_.fill(0.0);}

  double time() const {return data_->time;}
  int contactCount() const {return data_->ncon;}
  const mjModel * model() const {return model_;}
  const mjData * data() const {return data_;}

private:
  struct Joint
  {
    int qpos_adr{0};
    int dof_adr{0};
    int actuator{0};
    double kv_over_kp{0.0};
    double target{0.0};
  };
  Wrench rawWrench() const;
  void applyMimic();

  mjModel * model_{nullptr};
  mjData * data_{nullptr};
  std::vector<Joint> joint_;
  std::vector<double> velocity_command_;
  int force_adr_{-1};
  int torque_adr_{-1};
  Wrench tare_{};
  double carry_{0.0};
};

}  // namespace sim_mujoco
